(() => {
 const L=window.NEMO_LANDING,state=window.NEMO_LANDING_STATE,config=state?.config||L.defaults;
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function visual(p){let key=p.visual;if(key?.startsWith('/media/')||key==='photo'){const image=el('img');image.src=key==='photo'?'assets/hero.png':key;image.alt=p.title;image.loading='lazy';return image;}const art=el('div',undefined,'atlas '+({home:'a-home',cafe:'a-cafe',estimate:'a-estimate',measure:'a-measure',material:'a-material',complete:'a-complete',office:'office-art',popup:'popup-art'}[key]||key||''));art.setAttribute('role','img');art.setAttribute('aria-label',p.title);return art;}
 function renderProjects(category){const strip=document.querySelector('.portfolio-strip');strip.replaceChildren();const pool=state?.projects||[];for(const p of L.pickProjects(pool,category,6)){const card=el('button',undefined,'project-card');card.type='button';card.dataset.project=p.id;card.dataset.category=p.category;const image=el('div',undefined,'project-image');image.appendChild(visual(p));const caption=el('div',undefined,'project-caption');caption.append(el('span',p.title),el('span','↗'));card.append(image,caption,el('small',[...new Set([p.category,p.showMeta===false?'':p.style,p.kind].filter(Boolean))].join(' · ')));strip.appendChild(card);}const all=el('a',undefined,'project-card project-all');all.href='portfolios.html'+(category==='전체'?'':'?space='+encodeURIComponent(category));all.dataset.category=category;const box=el('div',undefined,'project-image');box.append(el('span','더 많은 공간을 만나보세요.'),el('strong',category==='전체'?'포트폴리오 전체 보기':category+' 공간 전체 보기'),el('span','↗'));all.append(box,el('span','포트폴리오에서 더 살펴보기 ↗','project-all-caption'));strip.appendChild(all);}
 document.querySelector('.reviews-heading .eyebrow').textContent=config.reviewEyebrow;document.querySelector('#reviews-title').textContent=config.reviewTitle;
 const meta=document.querySelector('.review-map-meta p'),total=el('strong',config.totalProjects),abroad=el('span',config.overseasProjects,'project-counter');
 const abroadLabel=el('span');abroadLabel.append(document.createTextNode('('+config.overseasLabel+' '),abroad,document.createTextNode(')'));meta.replaceChildren(document.createTextNode(config.totalLabel+' - '),total,document.createTextNode(' '),abroadLabel);document.querySelector('.review-data-source').textContent=config.dataSource;
 const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function countUp(node){const raw=node.textContent,match=raw.match(/^(\d[\d,]*)(\+?)$/);if(!match)return;const target=Number(match[1].replaceAll(',',''));if(!Number.isSafeInteger(target)||target<1)return;const suffix=match[2],format=n=>(match[1].includes(',')?n.toLocaleString('en-US'):String(n))+suffix;node.textContent=format(0);const begin=performance.now();function frame(now){const progress=Math.min((now-begin)/1400,1);node.textContent=progress===1?raw:format(Math.floor(target*(1-Math.pow(1-progress,3))));if(progress<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);}
 if(!reducedMotion&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){observer.disconnect();countUp(total);countUp(abroad);}},{threshold:.6});observer.observe(document.querySelector('.review-map-meta'));}
 const track=document.querySelector('.review-track');track.replaceChildren(...config.marquee.map(r=>{const q=el('blockquote','“'+r.text+'”');q.appendChild(el('small',r.label));return q;}));document.querySelector('.review-board').hidden=config.marquee.length===0;
 const overseas=document.querySelector('.overseas-project-list');overseas.replaceChildren(...config.overseas.map(r=>{const li=el('li'),h=el('h4',r.country+' · '+r.title);li.appendChild(h);if(r.description)li.appendChild(el('p',r.description));return li;}));if(!config.overseas.length)overseas.appendChild(el('li','등록된 해외 프로젝트가 없습니다.'));
 const groups=L.groupReviews(config.domestic),map=document.querySelector('.review-map-canvas'),popup=document.querySelector('#map-review-popup');map.querySelectorAll('.review-pin').forEach(n=>n.remove());popup.setAttribute('role','region');popup.setAttribute('aria-label','지역 후기');popup.setAttribute('aria-live','polite');let selected=null,pinned=null,index=0,hideTimer;
 function hideReview(){clearTimeout(hideTimer);selected=null;pinned=null;popup.hidden=true;map.querySelectorAll('.review-pin').forEach(n=>{n.classList.remove('selected');n.setAttribute('aria-expanded','false');});}
 function showReview(group,pin,i=0){clearTimeout(hideTimer);selected=group;index=(i+group.reviews.length)%group.reviews.length;const r=group.reviews[index];popup.replaceChildren(el('span',[group.label,r.kind].filter(Boolean).join(' · '),'map-review-region'),el('strong',r.person,'map-review-person'),el('p','“'+r.quote+'”','map-review-quote'));if(group.reviews.length>1){const controls=el('div',undefined,'map-review-controls'),prev=el('button','←'),next=el('button','→');prev.type=next.type='button';prev.setAttribute('aria-label','같은 지역 이전 후기');next.setAttribute('aria-label','같은 지역 다음 후기');prev.onclick=()=>showReview(group,pin,index-1);next.onclick=()=>showReview(group,pin,index+1);controls.append(prev,el('span',(index+1)+' / '+group.reviews.length),next);popup.appendChild(controls);}popup.hidden=false;map.querySelectorAll('.review-pin').forEach(n=>{n.classList.toggle('selected',n===pin);n.setAttribute('aria-expanded',String(n===pin));});}
 function scheduleHide(){clearTimeout(hideTimer);hideTimer=setTimeout(()=>{if(!pinned&&!map.contains(document.activeElement))hideReview();},280);}
 popup.addEventListener('pointerenter',()=>clearTimeout(hideTimer));popup.addEventListener('pointerleave',scheduleHide);popup.addEventListener('focusout',scheduleHide);
 for(const group of groups){const pin=el('button',undefined,'review-pin');pin.type='button';pin.dataset.region=group.id;pin.style.left=group.x+'%';pin.style.top=group.y+'%';pin.style.setProperty('--pulse-delay',-(groups.indexOf(group)%5)*.6+'s');pin.setAttribute('aria-label',group.label+' 후기 보기');pin.setAttribute('aria-controls','map-review-popup');pin.setAttribute('aria-expanded','false');pin.append(el('span',undefined,'pin-dot'),el('span',group.label,'pin-label'));
 pin.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch'&&!pinned)showReview(group,pin);else clearTimeout(hideTimer);});pin.addEventListener('pointerleave',scheduleHide);pin.addEventListener('focus',()=>{if(!pinned)showReview(group,pin);});pin.addEventListener('blur',scheduleHide);
 pin.addEventListener('click',()=>{if(pinned===group){hideReview();pin.blur();}else{pinned=group;showReview(group,pin,selected===group?index:0);}});map.appendChild(pin);}
 document.addEventListener('pointerdown',e=>{if(!e.target.closest('.review-pin,.map-review-popup'))hideReview();});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideReview();});
 window.NEMO_LANDING_VIEW={renderProjects,hideReview};
})();
